import { fixtureGrantSchema } from "../../src/types/productionIntroduction";

export function sample() {
  const at = (second: number) => new Date(second * 1000).toISOString();
  const ownership = {
    guildId: "guild",
    meetingId: "meeting",
    ownerInstanceId: "owner",
    executionVersion: 1,
    voiceOperationAttemptId: "attempt",
    sessionMode: "meeting",
  };
  const historyKey = {
    guildId: "guild",
    channelId_timestamp: `voice#${at(100)}`,
  };
  const grant = fixtureGrantSchema.parse({
    pk: "FIXTURE#grant",
    sk: "AUTHORITY",
    recordType: "fixture_grant",
    protocolVersion: 1,
    grantId: "grant",
    holdId: "hold",
    introductionId: "intro",
    revision: 1,
    inputProfile: "manual_script_v1",
    scriptSha256: "a".repeat(64),
    checklistSha256: "b".repeat(64),
    commandId: "command",
    meetingId: "meeting",
    guildId: "guild",
    voiceChannelId: "voice",
    textChannelId: "text",
    actorUserId: "actor",
    sessionMode: "meeting",
    state: "consumed",
    ownership,
    historyKey,
  });
  const fixtureInput = {
    schemaVersion: 1,
    profile: "manual_script_v1",
    reference: {
      holdId: "hold",
      introductionId: "intro",
      revision: 1,
      grantId: "grant",
    },
    commandId: "command",
    actorUserId: "actor",
    scriptSha256: "a".repeat(64),
    checklistSha256: "b".repeat(64),
    ownership,
    historyKey,
    observationStartedAt: at(101),
    captureStartedAt: at(102),
    captureEndedAt: at(302),
    observationEndedAt: at(302),
    acceptedSourceId: "user:actor",
    acceptedPcmChunks: 10000,
    acceptedPcmBytes: 19200000,
    unexpectedMembers: 0,
    unexpectedSourceAttempts: 0,
    rejectedMessages: 0,
    rejectedAttachments: 0,
    ttsAttempts: 0,
    continuityFailures: 0,
    overflow: false,
    state: "closed",
    failureReasons: [],
  };
  const fixtureGeneration = {
    schemaVersion: 1,
    submitted: 3,
    acknowledged: 3,
    missing: 0,
    overflow: false,
    tuples: ["transcription-audio-slow", "notes", "summary"].map((stage) => ({
      stage,
      requestedModel:
        stage === "transcription-audio-slow" ? "gpt-4o-transcribe" : "gpt-5.1",
      returnedModel: stage === "transcription-audio-slow" ? null : "gpt-5.1",
      providerRevision: "unavailable",
      prompt: {
        kind: "resolved",
        name: `fixture-${stage}`,
        version: 4,
        fallback: false,
      },
      count: 1,
    })),
  };
  const history = {
    ...historyKey,
    meetingId: "meeting",
    channelId: "voice",
    textChannelId: "text",
    ownerInstanceId: "owner",
    executionVersion: 1,
    status: "complete",
    transcribeMeeting: true,
    generateNotes: true,
    fixtureInput,
    fixtureGeneration,
    fixtureTranscript: {
      key: "generated/transcript.json",
      checksumSha256: "c".repeat(64),
      byteLength: 100,
      acknowledgment: { state: "acknowledged", versionId: "v1" },
    },
    checkpoint: {
      schemaVersion: 1,
      revision: 4,
      artifactFolder: "generated/",
      capture: {
        ...historyKey,
        channelId: "voice",
        meetingId: "meeting",
        ownerInstanceId: "owner",
        executionVersion: 1,
        reservedAt: at(100),
        captureStartedAt: at(102),
        requested: { transcribeMeeting: true, generateNotes: true },
      },
      manifest: {
        key: "generated/manifest.json",
        checksumSha256: "d".repeat(64),
        byteLength: 200,
      },
    },
    capture: { kind: "complete", startedAt: at(102), endedAt: at(302) },
    recovery: {
      disposition: "done",
      attempt: 0,
      executionVersion: 1,
      stage: "delivery",
      outcome: "completed",
      retry: { maxAttempts: 3, nextAttemptAt: null },
    },
    notesVersion: 1,
    notesChannelId: "text",
    notesMessageIds: ["notes1"],
    summaryMessageId: "summary1",
    transcriptS3Key: "generated/transcript.json",
    notesDeliveryTiming: {
      notesVersion: 1,
      path: "live",
      kind: "complete",
      firstAcknowledgedAt: at(310),
      completeAcknowledgedAt: at(312),
    },
    processing: {
      transcription: "ready",
      notes: "generated",
      summary: "generated",
    },
    delivery: {
      notes: { outcome: "complete", intended: 1, sent: 1, errors: [] },
      summary: { outcome: "edited_existing", intended: 1, sent: 1, errors: [] },
    },
  };
  return { grant, history, validFrom: 100, now: 320 };
}
